package com.learngraphicsprogramming.app.narration.phonemes

import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Test

/** Goldens generated by original en.py fba1236595f2d2bf21d414ba6e57d25256afada3,
 * spaCy 3.8.7/en_core_web_sm 3.8.0, and the pinned original US/GB BART checkpoints.
 * Tiny dictionary subsets retain exactly the upstream entries consulted by those sentences.
 * No model weight or alternate pronunciation algorithm is included in this test. */
class EnglishMisakiUpstreamGoldenTest {
    @Test fun completeSentencesMatchSelectedMisakiWithRealPosAndBartReference() {
        val dictionaries = JSONObject(DICTIONARIES)
        val fixtures = JSONArray(FIXTURES)
        for (index in 0 until fixtures.length()) {
            val fixture = fixtures.getJSONObject(index)
            val british = fixture.getBoolean("british")
            val dictionary = dictionaries.getJSONObject(if (british) "gb" else "us")
            val lexicon = MisakiLexicon(dictionary.getJSONObject("gold"), dictionary.getJSONObject("silver"), british)
            val raw = fixture.getJSONArray("tokens")
            val tokens = (0 until raw.length()).map { i ->
                val token = raw.getJSONObject(i)
                MisakiWord(token.getString("text"), token.getString("whitespace"), token.getString("tag"))
            }
            val fallback = fixture.getJSONObject("fallbacks")
            val actual = MisakiEnglishPipeline.speak(tokens, lexicon) { word -> fallback.getString(word) }
            assertEquals("${if (british) "GB" else "US"}: ${fixture.getString("text")}", fixture.getString("expected"), actual)
        }
    }

